import { SeedTsInferredAuthRefreshTokenClient } from "@fern/ts-inferred-auth-refresh-token";

const client = new SeedTsInferredAuthRefreshTokenClient({ baseUrl: "YOUR_BASE_URL" });
await client.auth.getTokenWithRefreshToken({
    refresh_token: "my-refresh-token",
    grant_type: "refresh_token",
    scope: "read"
});

